import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"60、【節】 兌下坎上","description":"橫渠易說 - 60、【節】 兌下坎上","frontmatter":{"title":"60、【節】 兌下坎上","description":"橫渠易說 - 60、【節】 兌下坎上"},"headers":[],"relativePath":"classics/hengqu/062.md","filePath":"classics/hengqu/062.md"}'),l={name:"classics/hengqu/062.md"};function t(n,a,s,d,c,o){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_60、【節】-兌下坎上" tabindex="-1">60、【節】 兌下坎上 <a class="header-anchor" href="#_60、【節】-兌下坎上" aria-label="Permalink to “60、【節】 兌下坎上”">​</a></h1><h3 id="彖曰-節亨-剛柔分而剛得中-苦節不可貞-其道窮也。說以行險-當位以節-中正以通。天地節而四時成-節以制度-不傷財-不害民。" tabindex="-1">彖曰：節亨，剛柔分而剛得中，“苦節不可貞”，其道窮也。說以行險，當位以節，中正以通。天地節而四時成，節以制度，不傷財，不害民。 <a class="header-anchor" href="#彖曰-節亨-剛柔分而剛得中-苦節不可貞-其道窮也。說以行險-當位以節-中正以通。天地節而四時成-節以制度-不傷財-不害民。" aria-label="Permalink to “彖曰：節亨，剛柔分而剛得中，“苦節不可貞”，其道窮也。說以行險，當位以節，中正以通。天地節而四時成，節以制度，不傷財，不害民。”">​</a></h3><h3 id="象曰-澤上有水-節-君子以制數度-議德行。" tabindex="-1">象曰：澤上有水，節，君子以制數度，議德行。 <a class="header-anchor" href="#象曰-澤上有水-節-君子以制數度-議德行。" aria-label="Permalink to “象曰：澤上有水，節，君子以制數度，議德行。”">​</a></h3><p>以苦節為貞，其道之窮必矣。</p><h3 id="初九-不出戶庭-無咎。-象曰-不出戶庭-知通塞也。" tabindex="-1">初九，不出戶庭，無咎。 象曰：“不出戶庭”，知通塞也。 <a class="header-anchor" href="#初九-不出戶庭-無咎。-象曰-不出戶庭-知通塞也。" aria-label="Permalink to “初九，不出戶庭，無咎。 象曰：“不出戶庭”，知通塞也。”">​</a></h3><p>見塞於九二，故不出。</p><h3 id="九二-不出門庭-兇。-象曰-不出門庭-兇-失時極也。" tabindex="-1">九二，不出門庭，兇。 象曰：“不出門庭，兇”，失時極也。 <a class="header-anchor" href="#九二-不出門庭-兇。-象曰-不出門庭-兇-失時極也。" aria-label="Permalink to “九二，不出門庭，兇。 象曰：“不出門庭，兇”，失時極也。”">​</a></h3><p>體柔位陰，故不出門庭兇。</p><h3 id="六三-不節若則嗟若-無咎。-象曰-不節之嗟-又誰咎也" tabindex="-1">六三，不節若則嗟若，無咎。 象曰：不節之嗟，又誰咎也! <a class="header-anchor" href="#六三-不節若則嗟若-無咎。-象曰-不節之嗟-又誰咎也" aria-label="Permalink to “六三，不節若則嗟若，無咎。 象曰：不節之嗟，又誰咎也!”">​</a></h3><p>處非其位，失節也，然能居不自安，則人將容之，故無咎。兌，說也，故能嗟諮取容。 王弼於此無咎又別立一例，只舊例亦可推行，但能嗟其不節有過之心則亦無咎也。若武帝下罪己之詔而天下悅，大人過既改，則復何咎之有!</p><h3 id="六四-安節-亨。-象曰-安節之亨-承上道也。" tabindex="-1">六四，安節，亨。 象曰：安節之亨，承上道也。 <a class="header-anchor" href="#六四-安節-亨。-象曰-安節之亨-承上道也。" aria-label="Permalink to “六四，安節，亨。 象曰：安節之亨，承上道也。”">​</a></h3><h3 id="九五-甘節-吉-往有尚。-象曰-甘節之吉-居位中也。" tabindex="-1">九五，甘節，吉，往有尚。 象曰：甘節之吉，居位中也。 <a class="header-anchor" href="#九五-甘節-吉-往有尚。-象曰-甘節之吉-居位中也。" aria-label="Permalink to “九五，甘節，吉，往有尚。 象曰：甘節之吉，居位中也。”">​</a></h3><p>以剛居中，得乎盛位，優為其節者也，守之不懈，富貴常保，故曰“往有尚”。</p><h3 id="上六-苦節-貞兇-悔亡。-象曰-苦節貞兇-其道窮也。" tabindex="-1">上六，苦節，貞兇，悔亡。 象曰：“苦節貞兇”，其道窮也。 <a class="header-anchor" href="#上六-苦節-貞兇-悔亡。-象曰-苦節貞兇-其道窮也。" aria-label="Permalink to “上六，苦節，貞兇，悔亡。 象曰：“苦節貞兇”，其道窮也。”">​</a></h3><p>處險之極，故曰“苦節”。苦節而不正，悔也，必正而兇，則道雖窮而悔亡；苦節反若獲吉，取悔必多。</p>',15)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
